import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Bidirectional catalog/read-point gate for cross-module runtime configuration. */
public final class RuntimeConfigUsageCheck{
 private static final Pattern CONSTANT=Pattern.compile("(?m)^\\s*([A-Z][A-Z0-9_]+)\\(\"([^\"]+)\"");
 public static void main(String[]args)throws Exception{Path root=Path.of(args[0]),catalog=root.resolve("server/GameCommon/src/main/java/com/aoo/bcg/common/config/RuntimeConfigKey.java");String definition=Files.readString(catalog);Map<String,String>keys=new LinkedHashMap<>();Matcher matcher=CONSTANT.matcher(definition);while(matcher.find())keys.put(matcher.group(1),matcher.group(2));StringBuilder corpus=new StringBuilder();try(var paths=Files.walk(root.resolve("server"))){for(Path path:paths.filter(Files::isRegularFile).filter(RuntimeConfigUsageCheck::canonical).filter(p->!p.equals(catalog)).toList())corpus.append(Files.readString(path)).append('\n');}List<String>failures=new ArrayList<>();for(var entry:keys.entrySet()){if(!Pattern.compile("\\bRuntimeConfigKey\\."+entry.getKey()+"\\b").matcher(corpus).find())failures.add("catalog key has no production read point: "+entry.getValue());}Matcher literal=Pattern.compile("\"([a-z][a-z0-9]*(?:[.-][a-z0-9]+){1,})\"").matcher(corpus);Set<String>catalogNames=new HashSet<>(keys.values());while(literal.find()){String value=literal.group(1);if((value.startsWith("aoo.")||value.startsWith("admin.")||value.startsWith("feature.")||value.startsWith("api.compatibility."))&&!catalogNames.contains(value))failures.add("uncatalogued runtime key literal: "+value);}Path out=root.resolve("work/audit/dead10-runtime-config-usage.txt");Files.createDirectories(out.getParent());Files.writeString(out,failures.isEmpty()?"DEAD10 passed: every runtime key has a production read point and no governed key is read outside the catalog. Operation switches are database-owned versioned resources.\n":String.join("\n",new TreeSet<>(failures))+"\n");if(!failures.isEmpty())throw new IllegalStateException("runtime config bidirectional gate failed: "+failures.size());System.out.println("Runtime config usage check passed: "+keys.size()+" keys.");}
 private static boolean canonical(Path value){String path=value.toString().replace('\\','/').toLowerCase(Locale.ROOT);return path.endsWith(".java")&&path.contains("/src/main/java/com/aoo/")&&!path.contains("/test/")&&!path.contains("/target/");}
}
